    private readonly GeoKernelViewerControl _viewer = new(); private readonly ListBox _directions = new(); private readonly TextBlock _summary = new() { Text = "Select a start and finish point.", TextWrapping = TextWrapping.Wrap }, _animationStatus = new() { Text = "Animation is waiting for a route.", TextWrapping = TextWrapping.Wrap }, _status = new(); private readonly Button _select = new() { Content = "Select route points", IsEnabled = false }, _play = new() { Content = "Play", IsEnabled = false }, _pause = new() { Content = "Pause", IsEnabled = false }, _resetAnimation = new() { Content = "Reset", IsEnabled = false }; private readonly DispatcherTimer _timer = new() { Interval = TimeSpan.FromMilliseconds(33) }; private readonly OverlayWindow _overlay;
    private AnimationRoutingEngine? _engine; private IReadOnlySet<int> _mainComponent = new HashSet<int>(); private RoutePoint? _start, _finish; private int _startNode = -1; private AnimationRoute? _route; private double _progress, _duration = 5000;
    public MainWindow()
    {
        Title = "RouteAnimation"; Width = 1200; Height = 760; WindowStartupLocation = WindowStartupLocation.CenterScreen; Icon = BitmapFrame.Create(new Uri("pack://application:,,,/Images/GeoKernelAppIcon.ico")); var root = new DockPanel(); Content = root; var toolbar = new StackPanel { Orientation = Orientation.Horizontal, Height = 34 }; toolbar.Children.Add(_select); var legend = new TextBlock { VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 0, 0) }; legend.Inlines.Add(new Run("●") { Foreground = Brush("#22C55E") }); legend.Inlines.Add(new Run(" Start   ")); legend.Inlines.Add(new Run("●") { Foreground = Brush("#EF4444") }); legend.Inlines.Add(new Run(" Finish")); toolbar.Children.Add(legend); DockPanel.SetDock(toolbar, Dock.Top); root.Children.Add(toolbar); DockPanel.SetDock(_status, Dock.Bottom); root.Children.Add(_status);
        var panel = new Grid { Width = 300, Margin = new Thickness(10) }; panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(22) }); panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(50) }); panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(55) }); panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(36) }); panel.RowDefinitions.Add(new RowDefinition()); Add(panel, new TextBlock { Text = "Route directions", FontWeight = FontWeights.Bold }, 0); Add(panel, _summary, 1); Add(panel, _animationStatus, 2); var buttons = new StackPanel { Orientation = Orientation.Horizontal }; buttons.Children.Add(_play); buttons.Children.Add(_pause); buttons.Children.Add(_resetAnimation); Add(panel, buttons, 3); Add(panel, _directions, 4); DockPanel.SetDock(panel, Dock.Right); root.Children.Add(panel); root.Children.Add(_viewer); _overlay = new OverlayWindow(_viewer);
        Loaded += LoadSample; LocationChanged += (_, _) => _overlay.SyncBounds(); SizeChanged += (_, _) => _overlay.SyncBounds(); StateChanged += (_, _) => _overlay.SyncBounds(); Closed += (_, _) => _overlay.Close(); _viewer.VisibleExtentChanged += (_, _) => _overlay.Redraw(); _viewer.MapMouseUp += MapClicked; _select.Click += (_, _) => BeginSelection(); _play.Click += (_, _) => Play(); _pause.Click += (_, _) => Pause(); _resetAnimation.Click += (_, _) => ResetAnimation(); _timer.Tick += (_, _) => TickAnimation();
